import Vue from 'vue'
import VueRouter from 'vue-router'

import CoreNeeds from '@/views/product/components/CoreNeeds.vue'
import KeyProblems from '@/views/product/components/KeyProblems.vue'
import Solutions from '@/views/product/components/Solutions.vue'
import Prototypes from '@/views/product/components/Prototypes.vue'
import Plan from '@/views/product/components/Plan.vue'

// 路由懒加载
const Home = () => import(/* webpackChunkName: "group-01" */ '../views/home/Home.vue')
const About = () => import(/* webpackChunkName: "group-01" */ '../views/about/About.vue')
const Product = () => import(/* webpackChunkName: "group-01" */'@/views/product/index.vue')
// const Store = () => import(/* webpackChunkName: "group-02" */ '../views/store/Store.vue')
const NotFind = () => import(/* webpackChunkName: "group-03" */ '../views/404/NotFind.vue')
const Test = () => import(/* webpackChunkName: "group-04" */ '@/views/test/Test.vue')
const Login = () => import(/* webpackChunkName: "group-05" */'@/views/login/Login.vue')
const Register = () => import(/* webpackChunkName: "group-05" */'@/views/login/Register.vue')

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    redirect: '/home'
  },
  {
    path: '/home',
    name: 'Home',
    component: Home
  },
  {
    path: '/about',
    name: 'About',
    component: About
  },
  /* {
    path: '/store',
    name: 'Store',
    component: Store
  }, */
  {
    path: '/test',
    name: 'Test',
    component: Test
  },
  {
    path: '/login',
    name: 'Login',
    component: Login
  },
  {
    path: '/register',
    name: 'Register',
    component: Register
  },
  {
    path: '/product',
    component: Product,
    children: [
      { path: '/', redirect: '/product/core-needs' },
      { path: '/product/core-needs', component: CoreNeeds },
      { path: '/product/key-problems', component: KeyProblems },
      { path: '/product/solutions', component: Solutions },
      { path: '/product/prototypes', component: Prototypes },
      { path: '/product/plan', component: Plan }
    ]
  },
  {
    path: '*',
    component: NotFind
  }
]

const router = new VueRouter({
  mode: 'hash',
  routes
})

// 路由的前置守卫
router.beforeEach((to, from, next) => {
  // 将滚动位置设置为顶部
  window.scrollTo(0, 0)
  next()
})

export default router
